<?php
namespace qqworld_collector\module\collect_filter; use qqworld_collector\lib; class qqworld_collector_parse_xw_qq_com_post_content extends lib { var $post_content = array(); public function __construct() { add_filter( 'qqworld-collector-parse-xw-qq-com-post-content', array($this, 'filter'), 10, 6 ); } public function filter($item, $source_link, $html, $type, $item_args, $download_args) { $json = json_decode($item, true); if ($json) { $item = ''; foreach ($json as $it) { switch ($it['type']) { case 1: $item .= '<p>' . $it['value'] . '</p>'; break; case 2: $item .= '<p><img src="' . $it['value'] . '" width="' . $it['width'] . '" height="' . $it['height'] . '" /></p>'; break; } } } return $item; } } new qqworld_collector_parse_xw_qq_com_post_content; ?>